def compute(vars):
    cloud_services = vars["v1"]
    other = vars["v2"]
    total = cloud_services + other
    return {
        "value": total,
        "trace": {
            "cloud_services": cloud_services,
            "other": other,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
